using System;
using LittleLeo.Events;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ForgeDiceReward", menuName = "Data/Rewards/ForgeDiceReward", order = 0)]
public class ForgeDiceReward : ConfirmReward
{
	private const string forgeEventButtonID = "ForgeEventButton";

	[Header("Forge Action")]
	[SerializeField]
	private DiceFace diceFace;

	[Header("Dice Rewards")]
	[SerializeField]
	private VoidEvent OnForgeDiceReward;

	[SerializeField]
	private GameObject forgeDiceRewardPanelPrefab;

	[SerializeField]
	private CameraReference dicePreviewCameraReference;

	[SerializeField]
	private ForgeDiceRewardReference forgeDiceRewardReference;

	[SerializeField]
	private GameObjectReference forgeDicePoolCanvasGameObjectReference;

	[SerializeField]
	private bool enableCharacter;

	[SerializeField]
	[ShowIf("enableCharacter")]
	private Character character;

	public DiceFace DiceFace => diceFace;

	public bool EnableCharacter => enableCharacter;

	public Character Character => character;

	public override string GetRewardName()
	{
		string text = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("ForgeEventButton");
		if (diceFace.ActionValue == EffectsValues.NO_VALUE)
		{
			text = ((!LanguagesIndexes.IsCurrentLanguageRussian()) ? text.Replace(" {1}", "").Replace("{1}", "") : text.Replace(" ×{1}", ""));
		}
		return Smart.Format(text, diceFace.BattleAction.GetActionName(), diceFace.ActionValue);
	}

	public override void GetReward(Action OnAfterConfirmingAction = null)
	{
		forgeDiceRewardReference.Set(this);
		if (forgeDicePoolCanvasGameObjectReference.value == null)
		{
			ReferenceSingleton<PoolHandler>.Instance.AddPool(forgeDiceRewardPanelPrefab);
			forgeDicePoolCanvasGameObjectReference.value = ReferenceSingleton<PoolHandler>.Instance.GetObject(forgeDiceRewardPanelPrefab.name);
			forgeDicePoolCanvasGameObjectReference.value.GetComponent<ForgeDicePoolCanvas>().SetOnAfterConfirmingAction(OnAfterConfirmingAction);
			forgeDicePoolCanvasGameObjectReference.value.GetComponent<Canvas>().worldCamera = dicePreviewCameraReference.value;
		}
		else
		{
			ReferenceSingleton<PoolHandler>.Instance.GetObject(forgeDiceRewardPanelPrefab.name).GetComponent<ForgeDicePoolCanvas>().SetOnAfterConfirmingAction(OnAfterConfirmingAction);
		}
		OnForgeDiceReward.Raise();
	}
}
